configfiles.configfile:
run_name: "galaxy_run" samples_file: "./samples.csv" output_dir: "./beegees_output"
#if $reference_source.ref_mode == "manual" sequence_reference_file: "${reference_source.sequence_reference_file}" #else: sequence_reference_file: "" #end if
fastp: adapter_r1: "${fastp.adapter_r1}" adapter_r2: "${fastp.adapter_r2}" extra_fastp_args: "${fastp.extra_fastp_args}"
#if $reference_source.ref_mode == "gene_fetch" run_gene_fetch: true gene_fetch: email: "${reference_source.gene_fetch.email}" api_key: "${reference_source.gene_fetch.api_key}" gene: "${reference_source.gene_fetch.gene}" type: "${reference_source.gene_fetch.fetch_type}" minimum_length: "${reference_source.gene_fetch.minimum_length}" input_type: "${reference_source.gene_fetch.input_type}" genbank: ${str(reference_source.gene_fetch.genbank).lower()} #else: run_gene_fetch: false #end if
downsampling: #if $downsampling.enabled enabled: true max_reads: ${downsampling.max_reads} #else: enabled: false max_reads: 0 #end if
barcode_recovery: r: #for $v in $barcode_recovery.r_values.split(',') - ${v.strip()} #end for s: #for $v in $barcode_recovery.s_values.split(',') - ${v.strip()} #end for n: ${barcode_recovery.n} C: ${barcode_recovery.C} t: ${barcode_recovery.t}
fasta_cleaner: consensus_threshold: ${fasta_cleaner.consensus_threshold} human_threshold: ${fasta_cleaner.human_threshold} at_difference: ${fasta_cleaner.at_difference} at_mode: "${fasta_cleaner.at_mode}" outlier_percentile: ${fasta_cleaner.outlier_percentile} #if $fasta_cleaner.reference_filter.use_ref_filter reference_dir: "${fasta_cleaner.reference_filter.reference_dir}" reference_filter_mode: "${fasta_cleaner.reference_filter.reference_filter_mode}" #else: reference_dir: null reference_filter_mode: "remove_similar" #end if
structural_validation: target: "${structural_validation.target}" verbose: ${str(structural_validation.verbose).lower()}
taxonomic_validation: #if $taxval.blast_db_source.source == "data_table" blast_db: "${taxval.blast_db_source.blast_db.fields.path}" #else: blast_db: "${taxval.blast_db_source.blast_db_file}" #end if #if $taxval.taxonomy_source.source == "data_table" db_taxonomy: "${taxval.taxonomy_source.db_taxonomy.fields.path}" #else: db_taxonomy: "${taxval.taxonomy_source.db_taxonomy_file}" #end if taxval_rank: "${taxval.taxval_rank}" #if $taxval.expected_taxonomy expected_taxonomy: "${taxval.expected_taxonomy}" #else: expected_taxonomy: null #end if verbose: ${str(taxval.verbose).lower()} min_pident: ${taxval.min_pident} min_length: ${taxval.min_length}
#expand macro="rules_configfile_block"
